\begin{enumerate}
\item[(a)] If every point of the plane is painted one of three colors,
do there necessarily exist two points of the same color exactly one
inch apart?
\item[(b)] What if ``three'' is replaced by ``nine''?
\end{enumerate}

Prove that $f(n) = 1-n$ is the only integer-valued function
defined on the integers that satisfies the following conditions.
\begin{itemize}
\item[(i)] $f(f(n)) = n$, for all integers $n$;
\item[(ii)] $f(f(n+2)+2) = n$ for all integers $n$;
\item[(iii)] $f(0) = 1$.
\end{itemize}

Let $\MM$ be a set of real $n \times n$ matrices such that
\begin{itemize}
\item[(i)] $I \in \MM$, where $I$ is the $n \times n$ identity matrix;

\item[(ii)] if $A \in \MM$ and $B \in \MM$, then either $AB \in \MM$ or
$-AB \in \MM$, but not both;

\item[(iii)] if $A \in \MM$ and $B \in \MM$, then either $AB = BA$ or
$AB = -BA$;

\item[(iv)] if $A \in \MM$ and $A \neq I$, there is at least one $B \in
\MM$ such that $AB = - BA$.
\end{itemize}
Prove that $\MM$ contains at most $n^2$ matrices.

A game starts with four heaps of beans, containing 3,4,5
and 6 beans. The two players move alternately. A move consists of
taking \textbf{either}
\begin{itemize}
\item[a)] one bean from a heap, provided at least two beans are
left behind in that heap, \textbf{or}

\item[b)] a complete heap of two or three beans.
\end{itemize}
The player who takes the last heap wins. To win the game, do you
want to move first or second? Give a winning strategy.

Let $S$ be the set of ordered triples $(a, b, c)$ of distinct elements
of a finite set $A$. Suppose that
\begin{enumerate}
\item $(a,b,c) \in S$ if and only if $(b,c,a) \in S$;
\item $(a,b,c) \in S$ if and only if $(c,b,a) \notin S$;
\item $(a,b,c)$ and $(c,d,a)$ are both in $S$ if and only if $(b,c,d)$
and $(d,a,b)$ are both in $S$.
\end{enumerate}
Prove that there exists a one-to-one function $g$ from $A$ to $R$ such
that $g(a) < g(b) < g(c)$ implies $(a,b,c) \in S$. Note: $R$ is the
set of real numbers.

Right triangle $ABC$ has right angle at $C$ and $\angle BAC =\theta$;
the point $D$ is chosen on $AB$ so that $|AC|=|AD|=1$; the point $E$
is chosen on $BC$ so that $\angle CDE = \theta$.  The perpendicular
to $BC$ at $E$ meets $AB$ at $F$.  Evaluate $\lim_{\theta\rightarrow 0}
|EF|$.

Find all pairs of real numbers $(x,y)$ satisfying the system
of equations
\begin{align*}
 \frac{1}{x} + \frac{1}{2y} &= (x^2+3y^2)(3x^2+y^2) \\
   \frac{1}{x} - \frac{1}{2y} &= 2(y^4-x^4).
\end{align*}

A Dyck $n$-path is a lattice path of  $n$  upsteps $(1,1)$ and  $n$
  downsteps $(1,-1)$
that starts at the origin  $O$  and never dips below the  $x$-axis.
A return is a maximal sequence of contiguous downsteps that terminates
on the  $x$-axis. For example, the Dyck 5-path illustrated has two returns,
of length  3  and  1  respectively.
\begin{center}
\begin{tikzpicture}[scale=.5]
\fill (0,0) circle (.2); \fill (1,1) circle (.2); \fill (2,2) circle (.2);
\fill (3,1) circle (.2); \fill (4,2) circle (.2); \fill (5,3) circle (.2);
\fill (6,2) circle (.2); \fill (7,1) circle (.2); \fill (8,0) circle (.2);
\fill (9,1) circle (.2); \fill (10,0) circle (.2);
\draw (0,0) -- (2,2) -- (3,1) -- (5,3) -- (8,0) -- (9,1) -- (10,0) -- cycle;
\draw (-.3,-.1) node[anchor=north] {$O$};
\end{tikzpicture}
\end{center}
Show that there is a one-to-one correspondence between the Dyck  $n$-paths
with no return of even length and the Dyck $(n-1)$-paths.

Let $S$ be a set of rational numbers such that
\begin{enumerate}
\item[(a)] $0 \in S$;
\item[(b)] If $x \in S$ then $x+1\in S$ and $x-1\in S$; and
\item[(c)] If $x\in S$ and $x\not\in\{0,1\}$, then $\frac{1}{x(x-1)}\in S$.
\end{enumerate}
Must $S$ contain all rational numbers?

Let $f: (1, \infty) \to \mathbb{R}$ be a differentiable function such that
\[
 f'(x) = \frac{x^2 - f(x)^2}{x^2 (f(x)^2 + 1)}
\qquad \mbox{for all $x>1$.}
\]
Prove that $\lim_{x \to \infty} f(x) = \infty$.

Let $G$ be a group, with operation $*$. Suppose that
\begin{enumerate}
\item[(i)]
$G$ is a subset of $\mathbb{R}^3$ (but $*$ need not be related to addition of vectors);
\item[(ii)]
For each $\mathbf{a},\mathbf{b} \in G$, either $\mathbf{a}\times \mathbf{b} = \mathbf{a}*\mathbf{b}$
or $\mathbf{a}\times \mathbf{b} = 0$ (or
both), where $\times$ is the usual cross product in $\mathbb{R}^3$.
\end{enumerate}
Prove that $\mathbf{a} \times \mathbf{b} = 0$ for all $\mathbf{a}, \mathbf{b} \in G$.

Let $F : \RR^2 \to \RR$ and $g : \RR \to \RR$ be twice
continuously differentiable functions with the following properties:
\begin{itemize}
\item $F(u,u) = 0$ for every $u \in \RR$;
\item for every $x \in \RR$, $g(x) > 0$ and $x^2 g(x) \leq 1$;
\item for every $(u,v) \in \RR^2$, the vector $\nabla F(u,v)$ is either $\mathbf{0}$ or parallel to the vector $\langle g(u), -g(v) \rangle$.
\end{itemize}
Prove that there exists a constant $C$ such that for every $n\geq 2$ and any $x_1,\dots,x_{n+1} \in \RR$, we have
\[
\min_{i \neq j} |F(x_i,x_j)| \leq \frac{C}{n}.
\]

Let $S$ be a class of functions from $[0, \infty)$ to $[0, \infty)$ that satisfies:
\begin{itemize}
\item[(i)]
The functions $f_1(x) = e^x - 1$ and $f_2(x) = \ln(x+1)$ are in $S$;
\item[(ii)]
If $f(x)$ and $g(x)$ are in $S$, the functions $f(x) + g(x)$ and $f(g(x))$ are in $S$;
\item[(iii)]
If $f(x)$ and $g(x)$ are in $S$ and $f(x) \geq g(x)$ for all $x \geq 0$, then the function
$f(x) - g(x)$ is in $S$.
\end{itemize}
Prove that if $f(x)$ and $g(x)$ are in $S$, then the function $f(x) g(x)$ is also in $S$.

